 /* ---------- Banner slideshow (trên header) ---------- */
 .index-carousel {
   position: relative;
   overflow: hidden;
   background: var(--bg-black);
 }

 .index-carousel_track {
   position: relative;
   aspect-ratio: 4 / 1;
   min-height: 120px;
 }

 .index-carousel_slide {
   position: absolute;
   inset: 0;
   opacity: 0;
   animation: index-carousel-fade 15s infinite;
 }

 .index-carousel_slide--1 { animation-delay: 0s; }
 .index-carousel_slide--2 { animation-delay: 5s; }
 .index-carousel_slide--3 { animation-delay: 10s; }

 .index-carousel_link { display: block; width: 100%; height: 100%; }

 .index-carousel_image {
   width: 100%;
   height: 100%;
   object-fit: cover;
   background: var(--img-frame);
 }

 /* Chấm chỉ báo (trang trí) */
 .index-carousel_dots {
   position: absolute;
   left: 0;
   right: 0;
   bottom: 12px;
   display: flex;
   justify-content: center;
   gap: 8px;
   pointer-events: none;
 }

 .index-carousel_dot {
   width: 24px;
   height: 4px;
   border-radius: var(--radius-pill);
   background: var(--pure-white);
   opacity: 0.4;
   animation: index-carousel-dot 15s infinite;
 }

 .index-carousel_dot--1 { animation-delay: 0s; }
 .index-carousel_dot--2 { animation-delay: 5s; }
 .index-carousel_dot--3 { animation-delay: 10s; }

 /* Tạm dừng khi rê chuột hoặc focus bàn phím */
 .index-carousel:hover .index-carousel_slide,
 .index-carousel:hover .index-carousel_dot,
 .index-carousel:focus-within .index-carousel_slide,
 .index-carousel:focus-within .index-carousel_dot {
   animation-play-state: paused;
 }

 @keyframes index-carousel-fade {
   0%      { opacity: 1; }
   28%     { opacity: 1; }
   33.33%  { opacity: 0; }
   94%     { opacity: 0; }
   100%    { opacity: 1; }
 }

 @keyframes index-carousel-dot {
   0%      { opacity: 1; background: var(--brand-purple); }
   28%     { opacity: 1; background: var(--brand-purple); }
   33.33%  { opacity: 0.4; background: var(--pure-white); }
   94%     { opacity: 0.4; background: var(--pure-white); }
   100%    { opacity: 1; background: var(--brand-purple); }
 }

 /* Người dùng tắt chuyển động: chỉ hiện banner đầu */
 @media (prefers-reduced-motion: reduce) {
   .index-carousel_slide,
   .index-carousel_dot { animation: none; }
   .index-carousel_slide--1 { opacity: 1; }
   .index-carousel_dot--1 { opacity: 1; background: var(--brand-purple); }
 }

 /* ---------- Khối chung của trang chủ ---------- */
 .index-section { padding: 56px 0; }
 .index-section--soft { background: var(--bg-soft); }

 .index-section_grid { display: grid; gap: 24px; }
 .index-section_grid--3 { grid-template-columns: repeat(3, 1fr); }
 .index-section_grid--4 { grid-template-columns: repeat(3, 1fr); }

 /* ---------- Banner ---------- */
 .index-hero {
   padding: 48px 0;
   background: var(--bg-soft);
   border-bottom: 1px solid var(--border-gray);
 }

 .index-hero_inner { display: flex; align-items: center; gap: 48px; }

 .index-hero_content {
   flex: 1 1 0;
   display: flex;
   flex-direction: column;
   gap: 24px;
 }

 .index-hero_title {
   font-family: var(--font-heading);
   font-size: clamp(2.25rem, 4vw, 2.75rem);
   font-weight: 800;
   line-height: 1.2;
   text-transform: uppercase;
 }

 .index-hero_title span { white-space: nowrap; }

 .index-hero_text { max-width: 440px; color: var(--text-muted); }

 .index-hero_actions { display: flex; flex-wrap: wrap; gap: 16px; }

 .index-hero_media { flex: 1.2 1 0; }

 .index-hero_image {
   width: 100%;
   aspect-ratio: 3 / 2;
   object-fit: cover;
   background: var(--img-frame);
   border-radius: var(--radius-image);
 }

 /* ---------- Bộ sưu tập đặc biệt ---------- */
 .index-collection {
   display: flex;
   align-items: center;
   gap: 48px;
   padding: 48px;
   background: var(--bg-soft);
   border: 1px solid var(--border-gray);
   border-radius: var(--radius-card);
 }

 .index-collection_content {
   flex: 1 1 0;
   display: flex;
   flex-direction: column;
   align-items: flex-start;
   gap: 16px;
 }

 .index-collection_title {
   font-family: var(--font-heading);
   font-size: clamp(1.5rem, 3vw, 1.75rem);
   font-weight: 700;
   text-transform: uppercase;
 }

 .index-collection_text { color: var(--text-muted); }

 .index-collection_media { flex: 1 1 0; }

 .index-collection_image {
   width: 100%;
   aspect-ratio: 3 / 2;
   object-fit: cover;
   background: var(--img-frame);
   border-radius: var(--radius-image);
 }

 /* ---------- Responsive ---------- */
 @media (max-width: 900px) {
   .index-hero { padding: 32px 0; }

   .index-hero_inner,
   .index-collection { flex-direction: column; align-items: stretch; gap: 32px; }

   .index-collection { padding: 32px 24px; }
   .index-hero_text { max-width: none; }

   .index-section_grid--3,
   .index-section_grid--4 { grid-template-columns: repeat(2, 1fr); }
 }

 @media (max-width: 600px) {
   .index-section { padding: 40px 0; }
   .index-section_grid--3 { grid-template-columns: 1fr; }
   .index-section_grid--4 { grid-template-columns: 1fr; gap: 16px; }
   .index-hero_actions .btn { flex: 1 1 100%; }
   .index-hero_title { font-size: clamp(1.75rem, 8vw, 2.25rem); }
   .index-hero_title span { white-space: normal; }
 }

